// Regenerates index.ts for the helius-webhook edge function.
//
// The Supabase MCP `deploy_edge_function` tool only accepts inline file
// content, so to keep the deploy payload small and free of escaping hazards we
// embed event-only slices of the program IDLs as a single gzip+base64 blob and
// inflate it at runtime via DecompressionStream. Run this after syncing IDLs:
//
//   node supabase/functions/helius-webhook/build-bundle.mjs
//
import { readFileSync, writeFileSync } from "node:fs";
import { gzipSync } from "node:zlib";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const sharedIdl = join(here, "..", "_shared", "idl");

const PROGRAMS = ["nave_core", "nave_governance", "nave_execution"];

// Build an event-decoding-only IDL slice: BorshEventCoder needs `events` plus
// any `types` they reference. Accounts, instructions, and errors are dropped.
function sliceIdl(full) {
  const eventNames = new Set((full.events || []).map((e) => e.name));
  const typeByName = Object.fromEntries((full.types || []).map((t) => [t.name, t]));
  const needed = new Set();
  const visit = (name) => {
    if (needed.has(name) || !typeByName[name]) return;
    needed.add(name);
    const scan = (node) => {
      if (!node) return;
      if (Array.isArray(node)) return node.forEach(scan);
      if (typeof node === "object") {
        if (node.defined?.name) visit(node.defined.name);
        if (typeof node.defined === "string") visit(node.defined);
        for (const k in node) scan(node[k]);
      }
    };
    scan(typeByName[name].type);
  };
  for (const n of eventNames) visit(n);
  return {
    address: full.address,
    metadata: full.metadata,
    instructions: [],
    accounts: [],
    events: full.events || [],
    errors: [],
    types: (full.types || []).filter((t) => needed.has(t.name)),
  };
}

const combined = {};
for (const p of PROGRAMS) {
  combined[p] = sliceIdl(JSON.parse(readFileSync(join(sharedIdl, `${p}.json`), "utf8")));
}
const idlB64 = gzipSync(Buffer.from(JSON.stringify(combined), "utf8"), { level: 9 }).toString("base64");

const body = `import { BorshEventCoder } from "npm:@coral-xyz/anchor@0.32.1";

// ─── Embedded event-only IDL slices (gzip + base64) ──────────────────────────
// Generated by build-bundle.mjs from ../_shared/idl/*.json. Compressed to keep
// the deploy payload small; inflated at runtime. Re-run the script after IDL
// changes: node supabase/functions/helius-webhook/build-bundle.mjs
const IDL_GZIP_B64 =
  "${idlB64}";

// deno-lint-ignore no-explicit-any
async function inflateIdls(): Promise<Record<string, any>> {
  const bytes = Uint8Array.from(atob(IDL_GZIP_B64), (c) => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  const text = new TextDecoder().decode(await new Response(stream).arrayBuffer());
  return JSON.parse(text);
}

let coderPromise: Promise<{ name: string; coder: BorshEventCoder }[]> | null = null;
function getCoders() {
  if (!coderPromise) {
    coderPromise = inflateIdls().then((idls) =>
      ["nave_core", "nave_governance", "nave_execution"].map((name) => ({
        name,
        coder: new BorshEventCoder(idls[name]),
      }))
    );
  }
  return coderPromise;
}

// ─── CORS ────────────────────────────────────────────────────────────────────
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Indexer-Secret",
};

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

/** Length-checked, constant-time string comparison (avoids timing oracles). */
function constantTimeEqual(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const PROGRAM_DATA_PREFIX = "Program data: ";

/** Candidate fields that identify the human actor of an event. */
const ACTOR_FIELDS = [
  "authority",
  "founder",
  "proposer",
  "voter",
  "guardian",
  "depositor",
  "executor",
  "creator",
  "feeCollector",
  "holder",
  "reviewer",
  "approver",
  "agent",
  "recipient",
  "triggered_by",
  "triggeredBy",
];

const AGENT_ROLE_BY_EVENT: Record<string, string> = {
  ExecutiveApprovedEvent: "executive",
  AgentApprovalEvent: "executive",
  FinancialApprovedEvent: "financial",
  OversightApprovedEvent: "oversight",
  OperationalHaltEvent: "operational",
  OperationalClearEvent: "operational",
};

// deno-lint-ignore no-explicit-any
function sanitize(value: any): any {
  if (value === null || value === undefined) return value;
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "object") {
    if (typeof value.toBase58 === "function") return value.toBase58();
    if (typeof value.toString === "function" && value._bn !== undefined) return value.toString();
    if (Array.isArray(value)) return value.map(sanitize);
    if (value instanceof Uint8Array) return Array.from(value);
    // deno-lint-ignore no-explicit-any
    const out: Record<string, any> = {};
    for (const [k, v] of Object.entries(value)) out[k] = sanitize(v);
    return out;
  }
  return value;
}

interface ParsedEvent {
  dao_onchain_address: string;
  event_type: string;
  description: string;
  actor: string;
  agent_role?: string;
  tx_signature: string;
  slot: number;
  block_time?: string;
  raw_data?: Record<string, unknown>;
}

const RPC_URL = Deno.env.get("SOLANA_RPC_URL") || "";

/** Enhanced payloads omit raw logs; re-fetch them via getTransaction when needed. */
async function fetchLogMessages(signature: string): Promise<string[]> {
  if (!RPC_URL || !signature) return [];
  try {
    const res = await fetch(RPC_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "getTransaction",
        params: [signature, { commitment: "confirmed", maxSupportedTransactionVersion: 0 }],
      }),
    });
    const json = await res.json();
    return json?.result?.meta?.logMessages ?? [];
  } catch {
    return [];
  }
}

// deno-lint-ignore no-explicit-any
async function decodeLogs(logs: string[]): Promise<{ name: string; data: any }[]> {
  const coders = await getCoders();
  // deno-lint-ignore no-explicit-any
  const out: { name: string; data: any }[] = [];
  for (const line of logs) {
    if (!line.startsWith(PROGRAM_DATA_PREFIX)) continue;
    const b64 = line.slice(PROGRAM_DATA_PREFIX.length).trim();
    for (const { coder } of coders) {
      try {
        const decoded = coder.decode(b64);
        if (decoded) {
          out.push(decoded);
          break;
        }
      } catch {
        // Not an event for this program; try the next coder.
      }
    }
  }
  return out;
}

// deno-lint-ignore no-explicit-any
function pickActor(data: any): string {
  for (const f of ACTOR_FIELDS) {
    if (data[f]) {
      const v = data[f];
      return typeof v.toBase58 === "function" ? v.toBase58() : String(v);
    }
  }
  return "";
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  // ── Auth: header-only shared secret, constant-time compared ──────────────
  // The ?secret= query-param path was removed: query strings leak into proxy,
  // CDN, and platform access logs. Configure the Helius webhook with an
  // Authorization: Bearer <secret> header (or X-Indexer-Secret).
  const indexerSecret = Deno.env.get("NAVE_INDEXER_SECRET");
  if (!indexerSecret) {
    return jsonResponse({ error: "Indexer not configured" }, 500);
  }
  const provided =
    req.headers.get("Authorization")?.replace(/^Bearer\\s+/i, "") ||
    req.headers.get("X-Indexer-Secret") ||
    "";
  if (!constantTimeEqual(provided, indexerSecret)) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  try {
    const payload = await req.json();
    // Helius sends an array of transactions (raw or enhanced).
    const txs: unknown[] = Array.isArray(payload) ? payload : [payload];

    const events: ParsedEvent[] = [];

    for (const tx of txs) {
      // deno-lint-ignore no-explicit-any
      const t = tx as any;

      const signature: string =
        t?.signature ||
        t?.transaction?.signatures?.[0] ||
        t?.transaction?.signature ||
        "";

      // Raw webhooks include logs inline; enhanced webhooks do not, so fall back
      // to a getTransaction RPC fetch (requires SOLANA_RPC_URL).
      let logs: string[] = t?.meta?.logMessages || t?.logs || [];
      if ((!Array.isArray(logs) || logs.length === 0) && signature) {
        logs = await fetchLogMessages(signature);
      }
      if (!Array.isArray(logs) || logs.length === 0) continue;

      const slot: number = t?.slot || 0;
      const blockTimeSec: number | undefined = t?.blockTime ?? t?.timestamp;
      const block_time = blockTimeSec ? new Date(blockTimeSec * 1000).toISOString() : undefined;

      for (const { name, data } of await decodeLogs(logs)) {
        const dao = data.dao ?? data.daoRegistry;
        const dao_onchain_address =
          dao && typeof dao.toBase58 === "function" ? dao.toBase58() : dao ? String(dao) : "";

        events.push({
          dao_onchain_address,
          event_type: name,
          description: \`On-chain event: \${name}\`,
          actor: pickActor(data),
          agent_role: AGENT_ROLE_BY_EVENT[name],
          tx_signature: signature,
          slot,
          block_time,
          raw_data: sanitize(data),
        });
      }
    }

    if (events.length === 0) {
      return jsonResponse({ success: true, decoded: 0, forwarded: 0, message: "No Nave events in batch" });
    }

    // ── Forward parsed events to index-events ─────────────────────────────
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const resp = await fetch(\`\${supabaseUrl}/functions/v1/index-events\`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: \`Bearer \${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}\`,
        // Pass the indexer secret in a header rather than the JSON body so it
        // does not surface in request-body logs.
        "X-Indexer-Secret": indexerSecret,
      },
      body: JSON.stringify({ events }),
    });

    const result = await resp.json();
    if (!resp.ok) {
      return jsonResponse({ error: "index-events rejected batch", detail: result }, 502);
    }

    return jsonResponse({ success: true, decoded: events.length, forwarded: result.inserted ?? 0, index_result: result });
  } catch (err) {
    console.error("helius-webhook error:", err);
    return jsonResponse({ error: err instanceof Error ? err.message : "Internal error" }, 500);
  }
});
`;

writeFileSync(join(here, "index.ts"), body);
console.log("Wrote index.ts (" + body.length + " bytes); idl gzip b64 chars=" + idlB64.length);
